public static int findNthLeapYear(int Y, int N) {
  if (Y < 1 || N < 1) {
    throw new IllegalArgumentException("Invalid input");
  }

  int leapYears = 0;
  for (int i = Y; i <= Y + N; i++) {
    if (isLeapYear(i)) {
      leapYears++;
      if (leapYears == N) {
        return i;
      }
    }
  }

  throw new NoSuchElementException("No such leap year found");
}

public static int findNthLeapYear(int Y, int N) {
    // Check for invalid input
    if (Y <= 0 || N <= 0) {
        throw new IllegalArgumentException("Invalid input: Y and N must be positive integers.");
    }

    // Initialize variables
    int currentYear = Y;
    int leapYearCount = 0;

    // Loop through years until we reach the Nth leap year
    while (leapYearCount < N) {
        // Check if current year is a leap year
        if (isLeapYear(currentYear)) {
            leapYearCount++;
            // If we have reached the Nth leap year, return the year
            if (leapYearCount == N) {
                return currentYear;
            }
        }

        // Increment current year and try again
        currentYear++;
    }

    // If we reach here, we did not find the Nth leap year
    throw new RuntimeException("Could not find the " + N + "th leap year in the range from " + Y + " to " + currentYear);
