    List<List<Integer>> result = new ArrayList<>();
    if (nums.length == 1) {
        result.add(Arrays.asList(nums));
        return result;
    }
    for (int i = 0; i < nums.length; i++) {
        int[] remainingNums = new int[nums.length - 1];
        for (int j = 0; j < nums.length; j++) {
            if (i != j) {
                remainingNums[j - 1] = nums[j];
            }
