public int findLargestSubstring(List<String> strings) {
    // Initialize a map to store the indices of the strings
    Map<String, Integer> indices = new HashMap<>();

    // Iterate over the strings and store the indices of each string
    for (int i = 0; i < strings.size(); i++) {
        String string = strings.get(i);
        indices.put(string, i);
    }

    // Initialize the largest substring length and the index of the largest substring
    int largestSubstringLength = 0;
    int largestSubstringIndex = 0;

    // Iterate over the strings and check if the inverse of each string can be found as a substring
    for (int i = 0; i < strings.size(); i++) {
        String string = strings.get(i);
        int inverse = string.length() - 1;
        while (inverse >= 0) {
            String substring = string.substring(inverse);
            if (indices.containsKey(substring)) {
                int index = indices.get(substring);
                if (index > largestSubstringIndex) {
                    largestSubstringLength = string.length();
                    largestSubstringIndex = index;
                }
                break;
            }
            inverse--;
        }
    }

    return largestSubstringLength;
}

