        if (path[0] == start[0] && path[1] == start[1] || path[0] == end[0] && path[1] == end[1]) {
            connected = true;
            break;
        }
    }

    if (!connected) {
        return "cannot be travelled";
    }

    // Check if the starting n-tersection is in the path
    boolean startInPath = false;
    for (int[] path : paths) {
        if (path[0] == start[0] && path[1] == start[1]) {
            startInPath = true;
            break;
        }
    }

    // Check if the ending n-tersection is in the path
    boolean endInPath = false;
    for (int[] path : paths) {
        if (path[0] == end[0] && path[1] == end[1]) {
            endInPath = true;
            break;
        }
    }

    // If the starting n-tersection is in the path but the ending n-tersection is not,
    // or vice versa, then the travel is not possible
    if ((startInPath && !endInPath) || (!startInPath && endInPath)) {
        return "cannot be travelled";
    }

    return "can be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
if (n < 0 || start == null || end == null || paths == null) {
throw new IllegalArgumentException("Invalid input");
}

boolean[] visited = new boolean[n];
int[] parent = new int[n];
for (int i = 0; i < n; i++) {
parent[i] = -1;
}

visited[start[0]][start[1]] = true;

Queue<int[]> queue = new LinkedList<>();

queue.offer(start);

while (!queue.isEmpty()) {
int[] current = queue.poll();

for (int[] path : paths) {
if (path[0] == current[0] && path[1] == current[1]) {
queue.offer(path);
visited[path[0]][path[1]] = true;
parent[path[0]][path[1]] = current[0];
}
}

if (current[0] == end[0] && current[1] == end[1]) {
return "can be travelled";
}
}
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // perform validation on the input parameters
    if (n < 1 || start == null || start.length != 2 || end == null || end.length != 2 || paths == null || paths.length == 0) {
        throw new IllegalArgumentException("Invalid input parameters");
    }

    // check if the starting and ending n-tersections are adjacent
    if (start[0] == end[0] || start[1] == end[1]) {
        return "cannot be travelled";
    }

    // check if the starting n-tersection is valid
    if (!isValidPosition(start[0], start[1], n)) {
        return "cannot be travelled";
    }

    // check if the ending n-tersection is valid
    if (!isValidPosition(end[0], end[1], n)) {
        return "cannot be travelled";
    }

    // check if the paths array is valid
    for (int[] path : paths) {
        if (path.length != 2 || !isValidPosition(path[0], path[1], n)) {
            return "cannot be travelled";
        }
    }

    // check if the starting n-tersection is reachable from the ending n-tersection
    Deque<int[]> queue = new ArrayDeque<>();
    queue.add(start);
    Set<int[]> visited = new HashSet<>();
    while (!queue.isEmpty()) {
        int[] current = queue.removeFirst();
        if (current[0] == end[0] && current[1] == end[1]) {
            return "can be travelled";
        }
        for (int[] adjacent : getAdjacentPositions(current)) {
            if (!visited.contains(adjacent)) {
                visited.add(adjacent);
                queue.addLast(adjacent);
            }
        }
    }
    return "cannot be travelled";
}

