    // Check if the target is in the left or right half
    if (target < nums[pivot] && target >= nums[0]) {
        // Search in the left half
        return search(nums, 0, pivot - 1, target);
    } else if (target > nums[pivot] && target <= nums[nums.length - 1]) {
        // Search in the right half
        return search(nums, pivot + 1, nums.length - 1, target);
    } else {
        // Target not found
        return -1;
    }
}

