}

public int search(int[] nums, int target) {
    // Base case: if the array has only one element, return -1
    if (nums.length == 1) {
        return -1;
    }

    // Find the pivot element
    int pivot = nums[0];

    // Recursively search the left and right parts of the array
    int leftIndex = search(Arrays.copyOfRange(nums, 1, pivot), target);
    int rightIndex = search(Arrays.copyOfRange(nums, pivot, nums.length - 1), target);

    // If the target value is found in the left or right part of the array, return its index
    if (leftIndex != -1) {
        return leftIndex + 1;
    } else if (rightIndex != -1) {
        return rightIndex + pivot + 1;
    }

    // If the target value is not found in the left or right part of the array, return -1
    return -1;
}

public double trimMean(int[] arr) {
    // Check if the input array is null or empty
    if (arr == null || arr.length == 0) {
        throw new IllegalArgumentException("Invalid input array");
    }

    // Calculate the smallest 5% of the elements
    int[] smallest = new int[arr.length / 20];
    int i = 0;
    for (int x : arr) {
        if (i < smallest.length && x < smallest[i]) {
            smallest[i] = x;
            i++;
        }
    }
    Arrays.sort(smallest);

    // Calculate the largest 5% of the elements
    int[] largest = new int[arr.length / 20];
    i = 0;
    for (int x : arr) {
        if (i < largest.length && x > largest[i]) {
            largest[i] = x;
            i++;
        }
    }
    Arrays.sort(largest);

    // Calculate the mean of the remaining elements
    double mean = 0;
    int count = 0;
    for (int x : arr) {
        if (x < smallest[smallest.length - 1] && x > largest[0]) {
            mean += x;
            count++;
        }
    }
    mean /= count;

    // Return the mean with an error of 10^-5
    return (float)Math.round(mean * 100000) / 100000;
}

public double trimMean(int[] arr) {
    double[] sortedArr = Arrays.copyOf(arr, arr.length);
    Arrays.sort(sortedArr);

    int smallest = (int) (arr.length * 0.05);
    int largest = (int) (arr.length * 0.05) - 1;

    double sum = 0;
    for (int i = smallest; i < arr.length - largest; i++) {
        sum += sortedArr[i];
    }

    double mean = sum / (sortedArr.length - (2 * Math.min(smallest, largest)));

    return mean;
}

public double trimMean(int[] arr) {
