    Arrays.sort(arr);

    // Calculate the 5% trimmed mean
    int trimSize = (int) (arr.length * 0.05);
    int start = trimSize;
    int end = arr.length - trimSize;
    double trimmedMean = 0;
    for (int i = start; i < end; i++) {
        trimmedMean += arr[i];
    }
    trimmedMean /= end - start;

    return trimmedMean;
}

public double trimMean(int[] arr) {
    // Check for invalid input
    if (arr == null || arr.length == 0) {
        throw new IllegalArgumentException("Input array is null or empty");
    }

    // Calculate the mean of the input array
    double mean = Arrays.stream(arr).average().getAsDouble();

    // Calculate the number of elements to remove from the smallest and largest 5%
    int numRemoveSmallest5Pct = (int) (arr.length * 0.05);
    int numRemoveLargest5Pct = (int) (arr.length * 0.05);

    // Remove the smallest and largest 5% of elements
    int[] sortedArr = Arrays.stream(arr).sorted().toArray();
    int[] trimmedArr = new int[arr.length - numRemoveSmallest5Pct - numRemoveLargest5Pct];
    System.arraycopy(sortedArr, numRemoveSmallest5Pct, trimmedArr, 0, trimmedArr.length);
    System.arraycopy(sortedArr, sortedArr.length - numRemoveLargest5Pct, trimmedArr, numRemoveSmallest5Pct, numRemoveLargest5Pct);

    // Calculate the mean of the trimmed array
    double trimmedMean = Arrays.stream(trimmedArr).average().getAsDouble();

    return trimmedMean;
}

