public boolean canArrange(int[] arr, int k) {
    int n = arr.length;
    if (n % 2 != 0 || k <= 1) {
        return false;
    }

    // Sort the array in ascending order
    Arrays.sort(arr);

    // Initialize variables to keep track of pairs
    int pairCount = 0;
    int currentSum = 0;

    // Iterate through the array
    for (int i = 0; i < n; i++) {
        // Check if the current sum is divisible by k
        if (currentSum % k == 0) {
            pairCount++;
        }

        // Add the current element to the sum
        currentSum += arr[i];

        // Check if the number of pairs is equal to n/2
        if (pairCount == n / 2) {
            return true;
        }
    }

    // If we reach this point, it means that we did not find a pair that is divisible by k
    return false;
}

public boolean canArrange(int[] arr, int k) {
    if (arr.length % 2 == 1) {
        // If the length of the array is odd, it is not possible to divide it into n/2 pairs
        return false;
    }

    for (int i = 0; i < arr.length - 1; i += 2) {
        if (arr[i] % k != 0 || arr[i + 1] % k != 0) {
            // If any of the elements is not divisible by k, it is not possible to divide the array into n/2 pairs
            return false;
        }
    }

    return true;
}

public boolean canArrange(int[] arr, int k) {
    // Check if the input array is empty or has an odd number of elements
    if (arr.length == 0 || arr.length % 2 == 1) {
        return false;
    }

    // Check if the divisor is valid
    if (k <= 1) {
        return false;
    }

    // Initialize a hash table to store the remainder of each element modulo k
    HashMap<Integer, Integer> rems = new HashMap<>();
    for (int elem : arr) {
        int rem = elem % k;
        if (rems.containsKey(rem)) {
            rems.put(rem, rems.get(rem) + 1);
        } else {
            rems.put(rem, 1);
        }
    }

    // Check if there are an even number of elements with each remainder
    for (int rem : rems.keySet()) {
        if (rems.get(rem) % 2 == 1) {
            return false;
        }
    }

    return true;
}

public boolean canArrange(int[] arr, int k) {
    Set<Integer> squares = new HashSet<>();
    for (int i = 0; i < arr.length; i++) {
        int square = (int)Math.sqrt(arr[i]);
        if (squares.contains(square)) {
            return false;
        }
        squares.add(square);
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    int n = arr.length; // number of elements in the array
    int pairs = n / 2; // number of pairs to be formed

    // check if the given divisor is valid
    if (k <= 1 || k > n) {
        throw new IllegalArgumentException("Invalid divisor: " + k);
    }

    // initialize an array to store the sums of each pair
    int[] sums = new int[pairs];

    // iterate over the array and form pairs
    for (int i = 0; i < n; i += 2) {
        int sum = arr[i] + arr[i + 1];
        if (sum % k == 0) { // if the sum is divisible by the given divisor
            sums[i / 2] = sum; // store the sum
        } else {
            return false; // the array cannot be divided into pairs with given divisor
        }
    }

    // check if all pairs have the same sum
    for (int i = 0; i < pairs - 1; i++) {
        if (sums[i] != sums[i + 1]) {
            return false;
        }
    }

    return true; // if the array can be divided into pairs with given divisor
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    if (n <= 0 || edges == null || hasApple == null || edges.length == 0 || edges[0].length != 2 || hasApple.length != n) {
        throw new IllegalArgumentException("Invalid input");
    }

    // Initialize the map to store the distances and the previous node for each node
    Map<Integer, Integer> distances = new HashMap<>();
    Map<Integer, Integer> previous = new HashMap<>();
    for (int i = 0; i < n; i++) {
        distances.put(i, -1);
        previous.put(i, -1);
    }

    // Set the distance for node 0 to 0 and the previous node to -1
    distances.put(0, 0);
    previous.put(0, -1);

    // Initialize the queue to store the nodes to be visited
    Queue<Integer> queue = new LinkedList<>();
    queue.add(0);

    // Iterate through the edges and nodes
    while (!queue.isEmpty()) {
        int node = queue.poll();
        for (int i = 0; i < edges.length; i++) {
            int neighbor = edges[i][0] == node ? edges[i][1] : edges[i][0];
            if (hasApple[neighbor] && distances.get(neighbor) == -1) {
                distances.put(neighbor, distances.get(node) + 1);
                previous.put(neighbor, node);
                queue.add(neighbor);
            }
        }
    }

    // Find the shortest path from node 0 to the last node with an apple
    int distance = Integer.MAX_VALUE;
    int lastNode = -1;
    for (int i = 0; i < n; i++) {
        if (hasApple[i] && distances.get(i) != -1 && distances.get(i) < distance) {
            distance = distances.get(i);
            lastNode = i;
        }
    }

    // Return the minimum time required to collect all the apples and return to node 0
    return distance + 1;
}

