public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize the graph
    Graph graph = new Graph(n, edges);

    // Initialize the distance array
    int[] distance = new int[n];
    for (int i = 0; i < n; i++) {
        distance[i] = Integer.MAX_VALUE;
    }

    // Initialize the visited array
    boolean[] visited = new boolean[n];
    Arrays.fill(visited, false);

    // Start BFS from node 0
    Queue<Integer> queue = new LinkedList<>();
    queue.offer(0);
    visited[0] = true;
    distance[0] = 0;

    while (!queue.isEmpty()) {
        int node = queue.poll();
        for (int neighbor : graph.neighbors(node)) {
            if (!visited[neighbor]) {
                visited[neighbor] = true;
                distance[neighbor] = distance[node] + 1;
                if (hasApple[neighbor]) {
                    return distance[neighbor];
                }
                queue.offer(neighbor);
            }
        }
    }

    // If no apple is found, return 0
    return 0;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize a disjoint set data structure to keep track of the connected components
    DisjointSet ds = new DisjointSet(n);

    // Iterate over the edges and union the connected components
    for (int[] edge : edges) {
        ds.union(edge[0], edge[1]);
    }

    // Find the connected components and determine the minimum time required to collect all the apples
    int minTime = 0;
    for (int i = 0; i < n; i++) {
        if (hasApple[i]) {
            if (ds.find(i) == ds.find(0)) {
                // If the node is not connected to the starting node, add the minimum time to travel to the node
                minTime += 1;
            }
        }
    }

    return minTime;
}

public String sortString(String s) {
    if (s == null || s.length() == 0) {
        return "";
    }

    int[] freq = new int[26];
    int size = s.length();
    char[] sortedChars = new char[size];

    // Update frequency array with the count of each character
    for (int i = 0; i < size; i++) {
        freq[(int)s.charAt(i) - 'a']++;
    }

    // Append characters to the result string in the desired order
    for (int i = 0; i < size; i++) {
        int minIndex = -1;
        int maxIndex = -1;

        for (int j = 0; j < 26; j++) {
            if (freq[j] > 0) {
                if (minIndex == -1 || (int)s.charAt(minIndex) > (int)s.charAt(j)) {
                    minIndex = j;
                }
                if (maxIndex == -1 || (int)s.charAt(maxIndex) < (int)s.charAt(j)) {
                    maxIndex = j;
                }
            }
        }
        sortedChars[i] = (char)(minIndex + 'a');
        freq[minIndex]--;
        sortedChars[size + i] = (char)(maxIndex + 'a');
        freq[maxIndex]--;
    }

    return new String(sortedChars);
}

public String sortString(String s) {
    // Initialize an empty string to store the sorted result
    String result = "";

    // Iterate through the characters in s
    for (char c : s.toCharArray()) {
        // Check if the character is already in the result
        if (result.contains(String.valueOf(c))) {
            // If it is, remove the first occurrence of the character from the result
            result = result.replaceFirst(String.valueOf(c), "");
        }

        // Append the character to the result
        result += c;
    }

    // Return the sorted result
    return result;
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        throw new IllegalArgumentException("Input string is null or empty");
    }

    PriorityQueue<Character> minHeap = new PriorityQueue<>();
    PriorityQueue<Character> maxHeap = new PriorityQueue<>(Comparator.reverseOrder());

    for (char c : s.toCharArray()) {
        minHeap.add(c);
        maxHeap.add(c);
    }

    StringBuilder result = new StringBuilder();

    while (!minHeap.isEmpty() && !maxHeap.isEmpty()) {
        char min = minHeap.poll();
        char max = maxHeap.poll();
        result.append(min).append(max);

        if (!minHeap.isEmpty() && minHeap.peek() == min) {
            minHeap.poll();
        }
        if (!maxHeap.isEmpty() && maxHeap.peek() == max) {
            maxHeap.poll();
        }
    }

    while (!minHeap.isEmpty()) {
        char min = minHeap.poll();
        result.append(min);
    }

    while (!maxHeap.isEmpty()) {
        char max = maxHeap.poll();
        result.append(max);
    }

    return result.toString();
}

public String sortString(String s) {
    String result = "";
    while (!s.isEmpty()) {
        char smallest = s.charAt(0);
        char largest = s.charAt(s.length() - 1);
        for (int i = 1; i < s.length(); i++) {
            if (s.charAt(i) < smallest) {
                smallest = s.charAt(i);
            }
            if (s.charAt(i) > largest) {
                largest = s.charAt(i);
            }
        }
        result += smallest;
        result += largest;
        s = s.replaceFirst(smallest, "");
        s = s.replaceFirst(largest, "");
    }
    return result;
}

public String sortString(String s) {
    StringBuilder result = new StringBuilder();
    while (!s.isEmpty()) {
        // Find the smallest character in s that is greater than the last appended character
        char smallestGreater = s.charAt(0);
        for (int i = 1; i < s.length(); i++) {
            if (s.charAt(i) > smallestGreater) {
                smallestGreater = s.charAt(i);
            }
        }
        result.append(smallestGreater);

        // Find the largest character in s that is smaller than the last appended character
        char largestSmaller = s.charAt(0);
        for (int i = 1; i < s.length(); i++) {
            if (s.charAt(i) < largestSmaller) {
                largestSmaller = s.charAt(i);
            }
        }
        result.append(largestSmaller);

        s = s.replaceFirst(smallestGreater + "", "");
        s = s.replaceFirst(largestSmaller + "", "");
    }
    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
