public int minCostClimbingStairs(int[] cost) {
    int minCost = 0;
    int index0 = 0;
    int index1 = 0;

    for (int i = 0; i < cost.length; i++) {
        if (i >= 1) {
            minCost = Math.min(index0, index1) + cost[i];
            index0 = index1;
            index1 = minCost;
        }
    }

    return minCost;
}

public int minCostClimbingStairs(int[] cost) {
    int minCost = 0;
    int currentCost = 0;
    for (int i = 0; i < cost.length; i++) {
        currentCost += cost[i];
        if (i > 0) {
            minCost = Math.min(minCost, currentCost - cost[i - 1]);
        }
    }
    return minCost;
}

public int minCostClimbingStairs(int[] cost) {
    // Check for invalid input
    if (cost == null || cost.length == 0) {
        throw new IllegalArgumentException("Invalid input");
    }

    // Initialize variables
    int minCost = 0;
    int currentCost = 0;
    int previousCost = 0;

    // Iterate over the cost array
    for (int i = 0; i < cost.length; i++) {
        // Calculate the current cost
        currentCost = cost[i] + Math.min(previousCost, minCost);

        // Update the minimum cost
        if (currentCost < minCost) {
            minCost = currentCost;
        }

        // Update the previous cost
        previousCost = currentCost;
    }

    return minCost;
}

public int minCostClimbingStairs(int[] cost) {
    int minCost = 0;
    int currentCost = 0;
    for (int i = 0; i < cost.length; i++) {
        currentCost += cost[i];
        if (i > 0 && currentCost < minCost) {
            minCost = currentCost;
        }
    }
    return minCost;
}

int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    int[] dp = new int[n];

    dp[0] = cost[0];
    dp[1] = cost[1];

    for (int i = 2; i < n; i++) {
        dp[i] = Math.min(dp[i - 1], dp[i - 2]) + cost[i];
    }

    return Math.min(dp[n - 1], dp[n - 2]);
}

