  if (s == null || s.length() == 0) {
    return false;
  }

  for (int i = 0; i < s.length() - k + 1; i++) {
    String substring = s.substring(i, i + k);
    if (!isBinaryString(substring)) {
      return false;
    }
  }

  return true;
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || k < 1) {
        throw new IllegalArgumentException("s and k must be non-null and positive");
    }

    for (int i = 0; i < Math.pow(2, k); i++) {
        String binaryString = String.format("%" + k + "s", Integer.toBinaryString(i)).replace(' ', '0');
        if (!s.contains(binaryString)) {
            return false;
        }
    }

    return true;
}

public boolean hasAllCodes(String s, int k) {
    boolean[] found = new boolean[1 << k];

    for (int i = 0; i + k - 1 < s.length(); i++) {
        int code = 0;
        for (int j = i; j < i + k; j++) {
            code <<= 1;
            code |= s.charAt(j) - '0';
        }
        found[code] = true;
    }

    for (int i = 0; i < found.length; i++) {
        if (!found[i]) {
            return false;
        }
    }

    return true;
}

public boolean hasAllCodes(String s, int k) {
    // Check if the input parameters are valid
    if (s == null || k < 1) {
        throw new IllegalArgumentException("Invalid input parameters");
    }

    // Check if the binary string is valid
    if (!s.matches("[01]*")) {
        throw new IllegalArgumentException("Invalid binary string");
    }

    // Check if the length of the binary string is >= the given length k
    if (s.length() < k) {
        throw new IllegalArgumentException("Binary string length is less than k");
    }

    // Initialize a set to store the substrings of length k
    Set<String> substrings = new HashSet<>();

    // Iterate over the binary string and find all substrings of length k
    for (int i = 0; i < s.length() - k + 1; i++) {
        String substring = s.substring(i, i + k);
        substrings.add(substring);
    }

    // Check if the set contains all possible substrings of length k
    for (int i = 0; i < 1 << k; i++) {
        String substring = Integer.toBinaryString(i).substring(1);
        if (!substrings.contains(substring)) {
            return false;
        }
    }

    return true;
}

