  String[] words = sentence.split(" ");

  // Iterate over each word in the sentence
  for (int i = 0; i < words.length; i++) {
    // If the current word is a prefix of the searchWord
    if (words[i].startsWith(searchWord)) {
      // Update the index to the current word's index
      index = i;
      // Break out of the loop since we have found a matching word
      break;
    }
  }

  // Return the index of the first matching word, or -1 if no match found
  return index;
}

