public int minInsertions(String s) {
    int balance = 0;
    int minOperations = 0;

    for (int i = 0; i < s.length(); i++) {
        char ch = s.charAt(i);
        if (ch == '(') {
            balance++;
        } else if (ch == ')') {
            if (balance == 0) {
                minOperations++;
            } else {
                balance--;
            }
        }
    }

    if (balance > 0) {
        minOperations += balance;
    }

    return minOperations;
}

public int minInsertions(String s) {

    // Initialize variables
    int left = 0;
    int right = 0;
    int insertions = 0;

    // Iterate through the string
    for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) == '(') {
            left++;
        } else {
            right++;
        }

        // Check if the number of left and right brackets are equal
        if (left == right) {
            continue;
        } else if (left > right) {
            insertions++;
            right++;
        } else {
            insertions++;
            left++;
        }
    }

    // Return the number of insertions required
    return insertions;
}

