public int minOperations(int n) {
    int[] arr = new int[n];
    for (int i = 0; i < n; i++) {
        arr[i] = (2 * i) + 1;
    }

    int minOperations = 0;
    while (true) {
        boolean isEqual = true;
        for (int i = 0; i < n - 1; i++) {
            if (arr[i] != arr[i + 1]) {
                isEqual = false;
                break;
            }
        }
        if (isEqual) {
            break;
        }

        int x = 0, y = 0;
        while (x < n && y < n) {
            if (arr[x] != arr[y]) {
                if (Math.abs(arr[x] - arr[y]) == 1) {
                    arr[x] -= 1;
                    arr[y] += 1;
                    minOperations++;
                    break;
                } else {
                    x++;
                    y++;
                }
            } else {
                x++;
                y++;
            }
        }
    }

    return minOperations;
}

public int minOperations(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer");
    }

    int[] arr = new int[n];
    for (int i = 0; i < n; i++) {
        arr[i] = (2 * i) + 1;
    }

    int minOps = 0;
    for (int i = 0; i < n; i++) {
        if (arr[i] != arr[0]) {
            int start = i;
            while (arr[start] != arr[0]) {
                start = (start + 1) % n;
                minOps++;
            }
            int end = i;
            while (arr[end] != arr[0]) {
                end = (end + n - 1) % n;
                minOps++;
            }
            if (start < end) {
                for (int j = start; j <= end; j++) {
                    arr[j] -= 1;
                    minOps++;
                }
            } else {
                for (int j = start; j >= end; j--) {
                    arr[j] -= 1;
                    minOps++;
                }
            }
        }
    }

    return minOps;
}

public int minOperations(int n) {
    int minOps = 0;
    for (int i = 0; i < n; i++) {
        minOps += Math.abs(arr[i] - 2 * i - 1);
    }
