}

public int kthFactor(int n, int k) {
    if (k < 1 || n < 1) {
        throw new IllegalArgumentException("n and k must be positive");
    }
    int[] factors = getFactors(n);
    if (factors.length < k) {
        return -1;
    }
    return factors[k - 1];
}

void getFactorCount(int n) {
