    for (int i = 2; i <= Math.sqrt(n); i++) {
        if (n % i == 0) {
            count++;
        }
    }
}

public int kthFactor(int n, int k) {
    // Special cases: When k is 0 or 1, there is only one factor, which is 1.
    if (k <= 1) {
        return 1;
    }

    // Initialize a set to store all the factors of n.
    Set<Integer> factors = new HashSet<>();

    // Iterate from 2 to the square root of n.
    for (int i = 2; i <= Math.sqrt(n); i++) {
        // If i is a factor of n, add it to the set.
        if (n % i == 0) {
            factors.add(i);
        }
    }

    // If there are less than k factors, return -1.
    if (factors.size() < k) {
        return -1;
    }

    // Iterate over the set of factors and return the kth element.
    int count = 1;
    for (Integer factor : factors) {
        if (count == k) {
            return factor;
        }
        count++;
    }

    // If we reach this point, there are fewer factors than k, so return -1.
    return -1;
}

public int kthFactor(int n, int k) {
    if (n < 1 || k < 1) {
        throw new IllegalArgumentException("n and k must be positive");
    }

    int[] factors = getFactors(n);
    if (k > factors.length) {
        return -1;
    }

    return factors[k - 1];
}

public int kthFactor(int n, int k) {
    // Calculate the number of factors that n has
    int numFactors = (int)Math.floor(Math.sqrt(n)) + 1;

    // Iterate from 1 to the number of factors and find the kth factor
    for (int i = 1; i <= numFactors; i++) {
        if (n % i == 0) {
            k--;
            if (k == 0) {
                return i;
            }
        }
    }

    // If we reach this point, it means that n has less than k factors, so we return -1
    return -1;
}

public String makeGood(String s) {
    StringBuilder result = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char currChar = s.charAt(i);
        if (Character.isLowerCase(currChar)) {
            if (i + 1 < s.length() && Character.isUpperCase(s.charAt(i + 1))) {
                // Skip the adjacent uppercase character
                i++;
            } else {
                // Add lowercase character to the result
                result.append(currChar);
