public int maxUniqueSplit(String s) {
    // Initialize a hash set to store unique substrings
    Set<String> uniqueSubstrings = new HashSet<>();

    // Initialize a pointer to keep track of the starting index of the current substring
    int startIndex = 0;

    // Loop through the string and split it into substrings
    for (int i = 0; i < s.length(); i++) {
        // If the current character is not the same as the previous character,
        // add the substring from the starting index to the current index to the set
        if (i == 0 || s.charAt(i) != s.charAt(i - 1)) {
            uniqueSubstrings.add(s.substring(startIndex, i));
            startIndex = i;
        }
    }

    // Add the last substring to the set
    uniqueSubstrings.add(s.substring(startIndex));

    // Return the size of the set, which is the maximum number of unique substrings
    return uniqueSubstrings.size();
}

public int maxUniqueSplit(String s) {
    Map<Character, Integer> frequencyMap = new HashMap<>();
    for (char c : s.toCharArray()) {
        frequencyMap.put(c, frequencyMap.getOrDefault(c, 0) + 1);
    }

    int maxUniques = 0;
    outer: for (char c : s.toCharArray()) {
        if (frequencyMap.get(c) <= 1) {
            continue;
        }

        frequencyMap.put(c, frequencyMap.get(c) - 1);
        int uniqueLength = 1;
        while (frequencyMap.get(c) > 0) {
            if (uniqueLength == s.length()) {
                break outer;
            }
            frequencyMap.put(c, frequencyMap.get(c) - 1);
            uniqueLength++;
        }

        maxUniques = Math.max(maxUniques, uniqueLength);
    }

    return maxUniques;
}

