    for (int i = 0; i < A.length - 1; i++) {
        int sum = A[i] + A[i + 1];
        currentPermutation.append(sum);
    }

    // Append the last element of the array to the current permutation
    currentPermutation.append(A[A.length - 1]);

    // Add the current permutation to the set of unique permutations
    permutations.add(currentPermutation.toString());

    // Return the size of the set, which is the number of unique permutations
    return permutations.size();
}

