public static int squarePermutations(int[] A) {

    // Initialize the result variable
    int result = 0;

    // Check if the input array is null or empty
    if (A == null || A.length == 0) {
        return result;
    }

    // Sort the input array in ascending order
    Arrays.sort(A);

    // Initialize a variable to keep track of the number of adjacent squares
    int consecutiveSquares = 0;

    // Iterate over the input array
    for (int i = 0; i < A.length - 1; i++) {
        // Calculate the sum of the current and next elements
        int sum = A[i] + A[i + 1];

        // Check if the sum is a perfect square
        if (sum % A[i] == 0 && (int) Math.sqrt(sum) == Math.sqrt(A[i])) {
            // Increment the number of adjacent squares
            consecutiveSquares++;
        } else {
            // Reset the number of adjacent squares if the current element is not a square
            consecutiveSquares = 0;
        }
    }

    // Check if the last element is a square
    if (A[A.length - 1] % A[A.length - 2] == 0 && (int) Math.sqrt(A[A.length - 1]) == Math.sqrt(A[A.length - 2])) {
        // Increment the number of adjacent squares if the last element is a square
        consecutiveSquares++;
    }

    // Calculate the number of permutations
    result = (int) Math.pow(2, consecutiveSquares);

    // Return the result
    return result;
}

public static int largestRectangleArea(int[] heights) {
