        area = heights[leftIndex] * (rightIndex - leftIndex + 1);
        maxArea = Math.max(maxArea, area);

        while (leftIndex < heights.length && heights[leftIndex] == heights[leftIndex - 1]) {
            leftIndex++;
        }

        while (rightIndex >= 0 && heights[rightIndex] == heights[rightIndex + 1]) {
            rightIndex--;
        }
    }

    return maxArea;
}

