public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer.");
    }

    // Initialize an array to store the ugly numbers
    int[] uglyNumbers = new int[n];
    uglyNumbers[0] = 1;

    // Initialize variables to keep track of the current index
    // in each sequence of ugly numbers
    int index2 = 0, index3 = 0, index5 = 0;

    for (int i = 1; i < n; i++) {
        // Calculate the next ugly number by finding the
        // minimum value among the next numbers in each sequence
        int min = Integer.MAX_VALUE;
        if (uglyNumbers[index2] * 2 < min) {
            min = uglyNumbers[index2] * 2;
        }
        if (uglyNumbers[index3] * 3 < min) {
            min = uglyNumbers[index3] * 3;
        }
        if (uglyNumbers[index5] * 5 < min) {
            min = uglyNumbers[index5] * 5;
        }

        // Add the next ugly number to the array and increment the index
        // in the corresponding sequence
        uglyNumbers[i] = min;
        if (min == uglyNumbers[index2] * 2) {
            index2++;
        }
        if (min == uglyNumbers[index3] * 3) {
            index3++;
        }
        if (min == uglyNumbers[index5] * 5) {
            index5++;
        }
    }

    return uglyNumbers[n - 1];
}

