public static int minPerfectSquareSum(int n) {
    // Initialize an empty set to store the perfect square numbers
    Set<Integer> perfectSquares = new HashSet<>();

    // Initialize the minimum number of perfect square numbers to sum up to n
    int minPerfectSquareSum = 0;

    // Iterate from 1 to n
    for (int i = 1; i <= n; i++) {
        // Check if i is a perfect square
        if (i % Math.sqrt(i) == 0) {
            // If i is a perfect square, add it to the set
            perfectSquares.add(i);

            // Increment the minimum number of perfect square numbers
            minPerfectSquareSum++;
        }
    }

    return minPerfectSquareSum;
}

